    $templateCache.put("views/search.html", "<!-- ============================================================\n     VIEW: search.html\n     Search page - live search input, genre/sort filters,\n     results grid and a \"no results\" empty state.\n     ============================================================ -->\n<div class=\"search-page\">\n\n  <!-- ================= SEARCH HEADER ================= -->\n  <section class=\"search-header\">\n    <h1 class=\"page-heading\">Find Movies, TV Series &amp; Anime</h1>\n\n    <div class=\"search-input-wrap\">\n      <i class=\"fa-solid fa-magnifying-glass\"></i>\n      <input\n        type=\"text\"\n        class=\"search-input-large\"\n        placeholder=\"Search movies, TV series, anime, e.g. Inception, Overflow, Demon Slayer...\"\n        ng-model=\"searchCtrl.query\"\n        ng-change=\"searchCtrl.onQueryChange()\"\n        ng-focus=\"searchCtrl.onInputFocus()\"\n        ng-blur=\"searchCtrl.closeSuggestions()\"\n        autocomplete=\"off\" />\n      <i class=\"fa-solid fa-xmark clear-icon\" ng-if=\"searchCtrl.query\" ng-click=\"searchCtrl.clearQuery()\" title=\"Clear\"></i>\n\n      <!-- Instant Live Suggestions Dropdown on Search Page -->\n      <div class=\"search-page-suggestions\" ng-if=\"searchCtrl.showSuggestions\" ng-mousedown=\"$event.preventDefault()\">\n        <div class=\"suggestions-loading\" ng-if=\"searchCtrl.isLoadingSuggestions\">\n          <i class=\"fa-solid fa-circle-notch fa-spin\"></i> Searching CinVerse...\n        </div>\n\n        <div class=\"suggestions-list\" ng-if=\"!searchCtrl.isLoadingSuggestions && searchCtrl.suggestions.length > 0\">\n          <a class=\"suggestion-item\" ng-repeat=\"item in searchCtrl.suggestions track by (item.media_type + '-' + item.id)\"\n            ng-href=\"{{ item.targetUrl }}\" ng-click=\"searchCtrl.selectSuggestion(item)\">\n            <img class=\"suggestion-poster\" ng-src=\"{{ searchCtrl.getPosterUrl(item.poster_path) }}\"\n              alt=\"{{ item.displayTitle }}\" />\n            <div class=\"suggestion-info\">\n              <span class=\"suggestion-title\">\n                {{ item.displayTitle }}\n                <span class=\"suggestion-tag-series\" ng-if=\"item.isTv\">SERIES</span>\n              </span>\n              <div class=\"suggestion-meta\">\n                <span class=\"suggestion-year\">{{ item.displayDate ? item.displayDate.slice(0,4) : 'TBA' }}</span>\n                <span class=\"suggestion-rating\" ng-if=\"item.vote_average\">\n                  <i class=\"fa-solid fa-star\"></i> {{ item.vote_average.toFixed(1) }}\n                </span>\n                <span class=\"suggestion-lang\" ng-if=\"item.original_language\">{{ item.original_language.toUpperCase() }}</span>\n              </div>\n            </div>\n            <i class=\"fa-solid fa-chevron-right suggestion-arrow\"></i>\n          </a>\n        </div>\n\n        <div class=\"suggestions-empty\"\n          ng-if=\"!searchCtrl.isLoadingSuggestions && searchCtrl.suggestions.length === 0 && searchCtrl.query.length >= 2\">\n          <i class=\"fa-solid fa-film\"></i> No instant suggestions found for \"{{ searchCtrl.query }}\"\n        </div>\n      </div>\n    </div>\n\n    <!-- ================= FILTERS ================= -->\n    <div class=\"search-filters\">\n      <select class=\"filter-select\" ng-model=\"searchCtrl.selectedGenre\">\n        <option value=\"\">All Genres</option>\n        <option ng-repeat=\"genre in searchCtrl.genres\" value=\"{{ genre.id }}\">{{ genre.name }}</option>\n      </select>\n\n      <select class=\"filter-select\" ng-model=\"searchCtrl.sortOption\">\n        <option value=\"relevance\">Sort: Relevance</option>\n        <option value=\"rating\">Sort: Highest Rated</option>\n        <option value=\"newest\">Sort: Newest First</option>\n        <option value=\"title\">Sort: A - Z</option>\n      </select>\n\n      <button class=\"btn btn-secondary btn-small\" ng-click=\"searchCtrl.resetFilters()\">\n        <i class=\"fa-solid fa-rotate-left\"></i> Reset\n      </button>\n    </div>\n  </section>\n\n  <!-- ================= LOADING SPINNER ================= -->\n  <div class=\"inline-loader\" ng-if=\"searchCtrl.isLoading\">\n    <div class=\"spinner\"></div>\n    <p>Searching movies...</p>\n  </div>\n\n  <!-- ================= ERROR MESSAGE ================= -->\n  <div class=\"error-banner\" ng-if=\"searchCtrl.errorMessage\">\n    <i class=\"fa-solid fa-triangle-exclamation\"></i> {{ searchCtrl.errorMessage }}\n  </div>\n\n  <!-- ================= NO RESULTS STATE ================= -->\n  <div class=\"no-results-state\" ng-if=\"!searchCtrl.isLoading && searchCtrl.hasSearched && searchCtrl.filteredResults().length === 0\">\n    <i class=\"fa-solid fa-ghost\"></i>\n    <h2>No Movies Found</h2>\n    <p>We couldn't find anything matching \"{{ searchCtrl.query }}\". Try a different title or adjust your filters.</p>\n  </div>\n\n  <!-- ================= EMPTY / PROMPT STATE (before first search) ================= -->\n  <div class=\"no-results-state\" ng-if=\"!searchCtrl.isLoading && !searchCtrl.hasSearched\">\n    <i class=\"fa-solid fa-clapperboard\"></i>\n    <h2>Start Typing to Search</h2>\n    <p>Discover thousands of movies. Just type a title above to get started.</p>\n  </div>\n\n  <!-- ================= RESULTS GRID ================= -->\n  <section class=\"movie-grid\" ng-if=\"!searchCtrl.isLoading && searchCtrl.filteredResults().length > 0\">\n    <div class=\"grid-item\" ng-repeat=\"movie in searchCtrl.filteredResults() track by (movie.media_type ? (movie.media_type + '-' + movie.id) : ('item-' + movie.id))\">\n      <movie-card movie=\"movie\"></movie-card>\n    </div>\n  </section>\n\n</div>\n");
